// Data + math for The Good Multiplier.
// All figures are approximate, published, rounded estimates (see footer of index.html).

export const POP = 8.1e9; // people on Earth, ~2025

export const INTERVENTIONS = {
  nets:   { name: 'Malaria nets',        cost: 5.5,  mortality: true  },
  deworm: { name: 'Deworming children',  cost: 1.5,  mortality: false },
  vita:   { name: 'Vitamin A doses',     cost: 1.0,  mortality: true  },
  cash:   { name: 'Direct cash grants',  cost: 1000, mortality: false },
};

export const DEFAULT_ALLOC = { nets: 40, deworm: 25, vita: 15, cash: 20 };

// Lives saved per dollar, across the mortality-focused programs.
// High end: best-estimate ~$4,500/life (GiveWell, AMF). Low end: $45,000/life to allow
// for scale-up inefficiency, delivery costs and uncertainty.
const LIVES_PER_DOLLAR_HIGH = 1 / 4500;
const LIVES_PER_DOLLAR_LOW  = 1 / 45000;

export function shares(alloc) {
  const keys = Object.keys(INTERVENTIONS);
  const sum = keys.reduce((a, k) => a + Math.max(0, alloc[k] || 0), 0);
  const out = {};
  for (const k of keys) out[k] = sum > 0 ? Math.max(0, alloc[k] || 0) / sum : 0;
  return out;
}

function split(total, alloc) {
  const sh = shares(alloc);
  const units = {};
  let mortalityPool = 0;
  for (const k of Object.keys(INTERVENTIONS)) {
    units[k] = (total * sh[k]) / INTERVENTIONS[k].cost;
    if (INTERVENTIONS[k].mortality) mortalityPool += total * sh[k];
  }
  return {
    sh, units,
    livesLow:  mortalityPool * LIVES_PER_DOLLAR_LOW,
    livesHigh: mortalityPool * LIVES_PER_DOLLAR_HIGH,
  };
}

// "If everyone on Earth gave $X/month" scenario.
export function computeScenario(monthlyPerPerson, alloc) {
  const pool = monthlyPerPerson * 12 * POP;
  return { pool, ...split(pool, alloc) };
}

// Personal pledge scenario.
export function computePledge(monthly, years, alloc) {
  const total = monthly * 12 * years;
  return { total, ...split(total, alloc) };
}

// Compact number formatting: 8100000000 -> "8.1B", 12345 -> "12.3K"
function trim(x) { return (Math.round(x * 10) / 10).toString().replace(/\.0$/, ''); }
export function fmt(n) {
  if (!isFinite(n)) return '—';
  const a = Math.abs(n);
  if (a >= 1e9) return trim(n / 1e9) + 'B';
  if (a >= 1e6) return trim(n / 1e6) + 'M';
  if (a >= 1e3) return trim(n / 1e3) + 'K';
  return (Math.round(n * 100) / 100).toString();
}
export function money(n) { return '$' + fmt(n); }

// Hero globe: a point-cloud Earth with arcs of "help" flowing toward regions of high need.
import * as THREE from 'three';

// Approximate lat/lon hubs in regions where cost-effective health programs operate.
const HUBS = [
  [1, 36], [6, 20], [-1, 36], [7, 78], [23, 90],
  [-13, 34], [3, 101], [-3, 23], [15, 77], [0, 135], [-8, 125], [11, 40],
];

function latLonToVec(lat, lon, r) {
  const phi = (90 - lat) * Math.PI / 180;
  const theta = (lon + 180) * Math.PI / 180;
  return new THREE.Vector3(
    -r * Math.sin(phi) * Math.cos(theta),
    r * Math.cos(phi),
    r * Math.sin(phi) * Math.sin(theta),
  );
}

export function initGlobe(canvas) {
  let renderer;
  try {
    renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
  } catch (e) {
    canvas.style.display = 'none';
    return;
  }
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(42, 1, 0.1, 120);
  camera.position.set(0, 0, 3.1);

  const group = new THREE.Group();
  group.rotation.z = 0.15;
  group.rotation.x = 0.28;
  scene.add(group);

  // --- Earth point cloud (fibonacci sphere) ---
  const R = 1, N = 2400;
  const pos = new Float32Array(N * 3);
  const col = new Float32Array(N * 3);
  const cA = new THREE.Color(0x5f8fd6); // deep blue
  const cB = new THREE.Color(0xf2b544); // amber
  const tmp = new THREE.Color();
  for (let i = 0; i < N; i++) {
    const y = 1 - (i / (N - 1)) * 2;
    const rad = Math.sqrt(Math.max(0, 1 - y * y));
    const th = i * 2.399963;
    pos[i * 3] = Math.cos(th) * rad * R;
    pos[i * 3 + 1] = y * R;
    pos[i * 3 + 2] = Math.sin(th) * rad * R;
    const t = Math.pow((y + 1) / 2, 2.2) * 0.55;
    tmp.copy(cA).lerp(cB, t);
    col[i * 3] = tmp.r; col[i * 3 + 1] = tmp.g; col[i * 3 + 2] = tmp.b;
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
  const points = new THREE.Points(geo, new THREE.PointsMaterial({
    size: 0.013, vertexColors: true, transparent: true, opacity: 0.95, sizeAttenuation: true,
  }));
  group.add(points);

  // faint wireframe shell
  const wire = new THREE.Mesh(
    new THREE.SphereGeometry(R * 1.002, 48, 32),
    new THREE.MeshBasicMaterial({ color: 0x2a3d5c, wireframe: true, transparent: true, opacity: 0.10 }),
  );
  group.add(wire);

  // --- background stars ---
  const SN = 550, sp = new Float32Array(SN * 3);
  for (let i = 0; i < SN; i++) {
    const v = new THREE.Vector3().randomDirection().multiplyScalar(25 + Math.random() * 40);
    sp[i * 3] = v.x; sp[i * 3 + 1] = v.y; sp[i * 3 + 2] = v.z;
  }
  const sgeo = new THREE.BufferGeometry();
  sgeo.setAttribute('position', new THREE.BufferAttribute(sp, 3));
  scene.add(new THREE.Points(sgeo, new THREE.PointsMaterial({
    color: 0xbfd4ff, size: 0.06, transparent: true, opacity: 0.45, sizeAttenuation: true,
  })));

  // --- arcs: pulses traveling from random points toward need hubs ---
  const ARC_N = 20;
  const arcs = [];
  const dotGeo = new THREE.SphereGeometry(0.017, 8, 8);
  function makeArc() {
    const hub = HUBS[(Math.random() * HUBS.length) | 0];
    const a = latLonToVec(hub[0] + (Math.random() * 36 - 18), hub[1] + (Math.random() * 48 - 24), R * 1.02);
    const b = latLonToVec(Math.random() * 160 - 80, Math.random() * 360 - 180, R * 1.02);
    const segs = 56;
    const pts = [];
    for (let i = 0; i <= segs; i++) {
      const t = i / segs;
      const v = a.clone().lerp(b, t).normalize().multiplyScalar(R * 1.02 + Math.sin(t * Math.PI) * 0.14);
      pts.push(v);
    }
    const line = new THREE.Line(
      new THREE.BufferGeometry().setFromPoints(pts),
      new THREE.LineBasicMaterial({ color: 0xf2b544, transparent: true, opacity: 0.20 }),
    );
    const dot = new THREE.Mesh(dotGeo, new THREE.MeshBasicMaterial({ color: 0xffd98a }));
    group.add(line); group.add(dot);
    return { pts, line, dot, t: Math.random(), speed: 0.10 + Math.random() * 0.22 };
  }
  for (let i = 0; i < ARC_N; i++) arcs.push(makeArc());

  // --- sizing ---
  function resize() {
    const w = canvas.clientWidth || 1, h = canvas.clientHeight || 1;
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
  }
  resize();
  if (typeof ResizeObserver !== 'undefined') new ResizeObserver(resize).observe(canvas);
  window.addEventListener('resize', resize, { passive: true });

  // --- gentle pointer parallax ---
  let mx = 0, my = 0;
  window.addEventListener('pointermove', (e) => {
    mx = e.clientX / window.innerWidth - 0.5;
    my = e.clientY / window.innerHeight - 0.5;
  }, { passive: true });

  // --- render loop (static single frame if reduced motion) ---
  const reduced = typeof matchMedia !== 'undefined' && matchMedia('(prefers-reduced-motion: reduce)').matches;
  const clock = new THREE.Clock();
  let raf = 0;
  function frame() {
    const dt = Math.min(clock.getDelta(), 0.05);
    group.rotation.y += dt * 0.055 + mx * 0.0005;
    group.rotation.x += (0.28 + my * 0.18 - group.rotation.x) * 0.02;
    for (const a of arcs) {
      a.t += a.speed * dt;
      if (a.t > 1) a.t = 0;
      const p = a.pts[Math.min(a.pts.length - 1, Math.floor(a.t * a.pts.length))];
      a.dot.position.copy(p);
      a.dot.scale.setScalar(0.6 + 0.9 * Math.sin(a.t * Math.PI));
    }
    renderer.render(scene, camera);
    if (!reduced) raf = requestAnimationFrame(frame);
  }
  frame();
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) cancelAnimationFrame(raf);
    else if (!reduced) { clock.getDelta(); raf = requestAnimationFrame(frame); }
  });
}

/* ============ The Good Multiplier ============ */
:root {
  --bg: #070a12;
  --bg2: #0a0f1b;
  --text: #e9edf5;
  --muted: #9aa7bd;
  --accent: #f2b544;
  --accent-soft: #ffd98a;
  --blue: #7dd3fc;
  --teal: #5eead4;
  --violet: #c4b5fd;
  --card: rgba(255, 255, 255, 0.04);
  --border: rgba(255, 255, 255, 0.09);
  --radius: 18px;
  --serif: "Iowan Old Style", Georgia, "Times New Roman", serif;
  --sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, monospace;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  background:
    radial-gradient(1100px 600px at 85% -5%, rgba(242, 181, 68, 0.07), transparent 60%),
    radial-gradient(900px 700px at -10% 30%, rgba(125, 211, 252, 0.05), transparent 60%),
    radial-gradient(1000px 800px at 50% 110%, rgba(94, 234, 212, 0.04), transparent 60%),
    var(--bg);
  color: var(--text);
  font-family: var(--sans);
  font-size: 17px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

.container { max-width: 1120px; margin: 0 auto; padding: 0 24px; }
.container.narrow { max-width: 860px; }
section { scroll-margin-top: 84px; }

h1, h2, h3 { font-family: var(--serif); font-weight: 600; line-height: 1.12; letter-spacing: -0.01em; }
h1 { font-size: clamp(2.4rem, 5.4vw, 4.2rem); margin: 0.35em 0 0.4em; }
h1 em { color: var(--accent); font-style: italic; }
h2 { font-size: clamp(1.7rem, 3.4vw, 2.6rem); margin: 0.3em 0 0.5em; }
h3 { font-size: 1.25rem; margin: 0 0 0.5em; }
p { margin: 0.6em 0; }
a { color: var(--accent-soft); }
.src { color: var(--muted); font-size: 0.85em; }
.fine { color: var(--muted); font-size: 0.82rem; line-height: 1.5; }

.eyebrow {
  font-family: var(--mono);
  font-size: 0.78rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--accent);
  margin: 0;
}

.section { padding: 110px 0; }
.section.alt { background: linear-gradient(180deg, rgba(255,255,255,0.018), rgba(255,255,255,0.028)); border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }
.section-lede { color: var(--muted); max-width: 62ch; font-size: 1.08rem; }

/* ---------- nav ---------- */
.nav {
  position: fixed; top: 0; left: 0; right: 0; z-index: 50;
  transition: background 0.25s ease, border-color 0.25s ease;
  border-bottom: 1px solid transparent;
}
.nav.scrolled { background: rgba(7, 10, 18, 0.82); backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px); border-bottom-color: var(--border); }
.nav-inner { display: flex; align-items: center; gap: 28px; height: 64px; }
.brand { font-family: var(--serif); font-size: 1.06rem; color: var(--text); text-decoration: none; white-space: nowrap; }
.brand-mark { color: var(--accent); }
.nav-links { display: flex; gap: 22px; margin-left: auto; }
.nav-links a { color: var(--muted); text-decoration: none; font-size: 0.92rem; }
.nav-links a:hover { color: var(--text); }

/* ---------- buttons ---------- */
.btn {
  display: inline-block; padding: 13px 26px; border-radius: 999px;
  font-family: var(--sans); font-size: 0.98rem; font-weight: 600;
  text-decoration: none; cursor: pointer; border: 1px solid transparent;
  transition: transform 0.15s ease, background 0.15s ease, border-color 0.15s ease;
}
.btn:hover { transform: translateY(-1px); }
.btn.primary { background: var(--accent); color: #1a1206; }
.btn.primary:hover { background: var(--accent-soft); }
.btn.ghost { background: rgba(255,255,255,0.05); color: var(--text); border-color: var(--border); }
.btn.ghost:hover { border-color: rgba(255,255,255,0.25); background: rgba(255,255,255,0.09); }
.btn.small { padding: 8px 18px; font-size: 0.88rem; }

/* ---------- hero ---------- */
.hero { position: relative; min-height: 100vh; display: flex; align-items: center; overflow: hidden; }
#globe { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.hero-veil {
  position: absolute; inset: 0; pointer-events: none;
  background:
    linear-gradient(180deg, rgba(7,10,18,0.55) 0%, rgba(7,10,18,0.25) 40%, var(--bg) 96%),
    radial-gradient(720px 480px at 30% 45%, rgba(7,10,18,0.72), transparent 70%);
}
.hero-inner { position: relative; z-index: 2; padding-top: 120px; padding-bottom: 90px; }
.lede { font-size: clamp(1.05rem, 1.6vw, 1.25rem); color: #c6cfdf; max-width: 56ch; }
.lede strong { color: var(--text); }
.cta-row { display: flex; flex-wrap: wrap; gap: 14px; margin: 30px 0 44px; }

.stat-strip {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 18px;
  margin: 0; padding: 22px 0 0; border-top: 1px solid var(--border); max-width: 900px;
}
.stat-strip > div { min-width: 0; }
.stat-num {
  display: block; font-family: var(--serif); font-size: clamp(1.5rem, 2.6vw, 2.1rem);
  color: var(--accent); font-variant-numeric: tabular-nums;
}
.stat-strip dd { margin: 2px 0 0; color: var(--muted); font-size: 0.85rem; line-height: 1.4; }
.stat-strip dd em { color: #c6cfdf; }
.strip-note { color: var(--muted); font-size: 0.9rem; margin-top: 14px; }
.strip-note strong { color: var(--accent-soft); }

/* ---------- cards ---------- */
.cards { display: grid; gap: 18px; margin-top: 34px; }
.cards.three { grid-template-columns: repeat(3, 1fr); }
.cards.menu { grid-template-columns: repeat(3, 1fr); }
.card {
  background: var(--card); border: 1px solid var(--border); border-radius: var(--radius);
  padding: 26px 26px 24px; transition: transform 0.2s ease, border-color 0.2s ease, background 0.2s ease;
}
.card:hover { transform: translateY(-3px); border-color: rgba(242, 181, 68, 0.35); background: rgba(255,255,255,0.055); }
.card-num { font-family: var(--mono); color: var(--accent); font-size: 0.8rem; letter-spacing: 0.2em; }
.card p { color: #c0c9d9; font-size: 0.95rem; }
.card .what { color: #c0c9d9; }
.card .cost { font-size: 1.05rem; color: var(--text); }
.card .cost strong { color: var(--accent); font-size: 1.3rem; }
.card .per { color: var(--accent-soft); font-size: 0.95rem; }
.card .evidence { color: var(--muted); font-size: 0.84rem; border-top: 1px dashed var(--border); padding-top: 12px; margin-top: 12px; }
.card .evidence strong { color: #c6cfdf; }

.big-takeaway {
  margin-top: 44px; font-family: var(--serif); font-size: clamp(1.25rem, 2.2vw, 1.7rem);
  line-height: 1.45; max-width: 46ch; color: var(--text);
}
.big-takeaway strong { color: var(--accent); }

/* ---------- math / pledge panels ---------- */
.math-grid { display: grid; grid-template-columns: 1fr 1.15fr; gap: 20px; margin-top: 36px; align-items: start; }
.panel {
  background: var(--card); border: 1px solid var(--border); border-radius: var(--radius);
  padding: 28px;
}
.alloc-title { margin: 26px 0 6px; font-family: var(--sans); font-size: 1rem; font-weight: 600; }
.alloc-title .hint { color: var(--muted); font-weight: 400; font-size: 0.8rem; }

.control { margin: 18px 0 6px; }
.control label { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-weight: 600; font-size: 0.98rem; }
.control output { font-family: var(--mono); color: var(--accent); font-size: 0.95rem; white-space: nowrap; }
.scale { display: flex; justify-content: space-between; color: var(--muted); font-size: 0.72rem; margin-top: 2px; }
.dot { display: inline-block; width: 10px; height: 10px; border-radius: 50%; background: var(--c, #fff); margin-right: 8px; }

input[type="range"] {
  -webkit-appearance: none; appearance: none; width: 100%; height: 26px; background: transparent; cursor: pointer; margin: 6px 0 0;
}
input[type="range"]::-webkit-slider-runnable-track { height: 6px; border-radius: 3px; background: linear-gradient(90deg, rgba(242,181,68,0.55), rgba(242,181,68,0.15)); }
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none; appearance: none; width: 20px; height: 20px; border-radius: 50%;
  background: var(--accent); border: 3px solid #1a1206; margin-top: -7px;
  box-shadow: 0 0 0 3px rgba(242,181,68,0.25);
}
input[type="range"]::-moz-range-track { height: 6px; border-radius: 3px; background: rgba(255,255,255,0.14); }
input[type="range"]::-moz-range-progress { height: 6px; border-radius: 3px; background: rgba(242,181,68,0.55); }
input[type="range"]::-moz-range-thumb { width: 15px; height: 15px; border-radius: 50%; background: var(--accent); border: 3px solid #1a1206; }
input[type="range"]:focus-visible { outline: 2px solid var(--accent); outline-offset: 4px; border-radius: 6px; }

.pool { display: flex; flex-direction: column; gap: 2px; padding-bottom: 18px; border-bottom: 1px solid var(--border); }
.pool-label { font-family: var(--mono); font-size: 0.75rem; letter-spacing: 0.18em; text-transform: uppercase; color: var(--muted); }
.pool-num { font-family: var(--serif); font-size: clamp(2.6rem, 4.5vw, 3.6rem); color: var(--accent); font-variant-numeric: tabular-nums; line-height: 1.05; }
.pool-sub { color: var(--muted); font-size: 0.88rem; }

.out-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin: 20px 0; }
.out { background: rgba(255,255,255,0.03); border: 1px solid var(--border); border-radius: 14px; padding: 14px 16px; }
.out-num { display: block; font-family: var(--serif); font-size: 1.7rem; color: var(--text); font-variant-numeric: tabular-nums; }
.out-label { color: var(--muted); font-size: 0.82rem; line-height: 1.4; display: block; }
.out-label small { opacity: 0.8; }

.lives { font-family: var(--serif); font-size: 1.15rem; color: var(--teal); margin: 8px 0 16px; }
.lives strong { color: #b8f5e8; }

.alloc-bar { display: flex; height: 12px; border-radius: 6px; overflow: hidden; gap: 2px; margin-bottom: 14px; }
.alloc-bar span { display: block; height: 100%; transition: width 0.25s ease; min-width: 0; }

.pl-list { list-style: none; margin: 18px 0 6px; padding: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 10px 18px; }
.pl-list li { color: #c0c9d9; font-size: 0.95rem; padding-left: 20px; position: relative; }
.pl-list li::before { content: "◆"; position: absolute; left: 0; color: var(--accent); font-size: 0.7rem; top: 0.35em; }
.pl-list li b { color: var(--text); font-variant-numeric: tabular-nums; }

.statement-box {
  margin-top: 18px; background: rgba(242,181,68,0.06); border: 1px solid rgba(242,181,68,0.3);
  border-radius: 14px; padding: 16px 18px;
}
.statement { font-family: var(--serif); font-size: 1.02rem; line-height: 1.55; color: #f3e6c8; margin: 0 0 12px; }

/* ---------- quiz ---------- */
.quiz { margin-top: 20px; }
.quiz h3 { margin-bottom: 4px; }
.quiz p { color: #c0c9d9; max-width: 70ch; }
.quiz-options { display: flex; flex-wrap: wrap; gap: 10px; margin: 16px 0 6px; }
.quiz-options button {
  font-family: var(--sans); font-size: 0.92rem; padding: 10px 18px; border-radius: 999px;
  background: rgba(255,255,255,0.05); color: var(--text); border: 1px solid var(--border); cursor: pointer;
  transition: border-color 0.15s ease, background 0.15s ease;
}
.quiz-options button:hover { border-color: rgba(242,181,68,0.5); }
.quiz-options button.correct { background: rgba(94,234,212,0.15); border-color: var(--teal); color: #b8f5e8; }
.quiz-options button.wrong { background: rgba(255,255,255,0.03); border-color: var(--border); color: var(--muted); text-decoration: line-through; }
.quiz-options button:disabled { cursor: default; }
.quiz-result { margin-top: 12px; color: #b8f5e8; font-size: 0.95rem; }

/* ---------- objections ---------- */
.obj-list { margin-top: 30px; display: grid; gap: 12px; }
.obj {
  background: var(--card); border: 1px solid var(--border); border-radius: 14px; padding: 0 22px;
  transition: border-color 0.2s ease;
}
.obj[open] { border-color: rgba(242,181,68,0.3); }
.obj summary {
  cursor: pointer; padding: 18px 0; font-family: var(--serif); font-size: 1.12rem; list-style: none; position: relative;
}
.obj summary::-webkit-details-marker { display: none; }
.obj summary::after { content: "+"; position: absolute; right: 4px; top: 14px; color: var(--accent); font-family: var(--mono); font-size: 1.2rem; }
.obj[open] summary::after { content: "–"; }
.obj summary:hover { color: var(--accent-soft); }
.obj p { color: #c0c9d9; padding-bottom: 20px; margin: 0; max-width: 68ch; }
.obj p em { color: var(--text); }

/* ---------- steps ---------- */
.steps { margin: 34px 0 0; padding: 0; list-style: none; counter-reset: step; display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
.steps li {
  counter-increment: step; background: var(--card); border: 1px solid var(--border); border-radius: var(--radius);
  padding: 24px 24px 22px 60px; position: relative; color: #c0c9d9; font-size: 0.97rem;
}
.steps li::before {
  content: counter(step, decimal-leading-zero);
